public static AuthMode ModeFor(string scheme) => scheme switch
{
    "Bearer" => AuthMode.Oidc,
    "LTI" => AuthMode.Lti13,
    "ApiKey" => AuthMode.LegacyKey,
    _ => throw new ArgumentException($"Unsupported scheme '{scheme}'", nameof(scheme))
};

public enum AuthMode { Oidc, Lti13, LegacyKey }

public static string Band(int percent) => percent switch
{
    < 0 or > 100 => throw new ArgumentOutOfRangeException(nameof(percent)),
    < 50 => "fail",
    < 70 => "pass",
    < 90 => "merit",
    _ => "distinction"
};

switch (token)
{
    case { Scheme: "LTI", Version: "1.3" }:
        ValidateLti13(token);
        break;
    case { Scheme: "Bearer" } t when t.ExpiresAt > DateTimeOffset.UtcNow:
        ValidateOidc(t);
        break;
    default:
        throw new InvalidOperationException("Token not usable.");
}

public enum AuthScheme { Lti, Oidc, ApiKey }

// Compiler-checked when all enum members covered:
string MapScheme(AuthScheme scheme) => scheme switch
{
    AuthScheme.Lti => "lti",
    AuthScheme.Oidc => "oidc",
    AuthScheme.ApiKey => "apikey"
};

// Runtime enum from wire — NOT closed; discard required:
AuthDecision Decide(int rawScheme, Token token) => rawScheme switch
{
    1 => MapLti(token),
    2 => MapOidc(token),
    3 => MapApiKey(token),
    _ => throw new ArgumentOutOfRangeException(nameof(rawScheme), rawScheme, "unknown scheme")
};
